import type { ReactNode } from "react";

type MarqueeProps = {
  children: ReactNode;
  reverse?: boolean;
  className?: string;
  itemClassName?: string;
};

export default function Marquee({
  children,
  reverse = false,
  className = "",
  itemClassName = "",
}: MarqueeProps) {
  return (
    <div className={`no-scrollbar flex w-full overflow-hidden ${className}`}>
      <div
        className={`flex w-max shrink-0 items-stretch gap-4 ${
          reverse ? "animate-marquee-reverse" : "animate-marquee"
        } hover:[animation-play-state:paused]`}
      >
        <div className={`flex shrink-0 items-stretch gap-4 ${itemClassName}`}>
          {children}
        </div>
        <div
          className={`flex shrink-0 items-stretch gap-4 ${itemClassName}`}
          aria-hidden="true"
        >
          {children}
        </div>
      </div>
    </div>
  );
}
